effect.shader:
void main() {
    vec4 topo = texture(inputImg, acScreenNorm);
    vec4 base = texture(originalImg, acScreenNorm);

    // A opacidade entra no alfa do que vem de cima: a 0 sobra a camada crua, e
    // no caminho é a mesma conta de uma camada com opacidade no AM e no Nova.
    float as_ = topo.a * clamp(opacidade, 0.0, 1.0);
    float ab = base.a;

    // A composição do W3C, a mesma da mesclagem de camada e da de efeito.
    vec3 mesclado = mesclarComoACamada(modo, base.rgb, topo.rgb);
    float a = as_ + ab * (1.0 - as_);
    vec3 cor = as_ * (1.0 - ab) * topo.rgb
             + as_ * ab * mesclado
             + (1.0 - as_) * ab * base.rgb;

    fragColor = a > 0.0 ? vec4(clamp(cor / a, 0.0, 1.0), a) : vec4(0.0);
}
